_m $'Another S3-compatible service' $'Otro servicio compatible con S3'
_m $'shown on the bucket in the Backblaze console, for instance s3.us-west-004.backblazeb2.com' $'se muestra en el bucket, en la consola de Backblaze; por ejemplo s3.us-west-004.backblazeb2.com'
_m $'<account ID>.r2.cloudflarestorage.com, shown on the R2 overview page' $'<ID de cuenta>.r2.cloudflarestorage.com, se muestra en la página de resumen de R2'
_m $'for instance {1}' $'por ejemplo {1}'
